command:
$ErrorActionPreference = "Stop"
git fetch origin main --no-tags --prune
if ($LASTEXITCODE -ne 0) { throw "fetch main failed" }
if ((git rev-parse origin/main).Trim() -ne "e92b2b8016728ed96fd3995b45f61ba5deaa5767") { throw "main moved" }

git -C $env:GITHUB_WORKSPACE push origin --delete work/model-streaming
if ($LASTEXITCODE -ne 0) { throw "model-streaming branch cleanup failed" }

Write-Host "MODEL_STREAMING_WORK_BRANCH_DELETED"
